update public.exercises set consigne = '<p>Votre neveu de 14 ans vient passer les vacances de printemps chez vous et vous lui cherchez une activité. Vous choisissez en fonction des critères suivants :</p><p>• adaptée à son âge ;<br>• activité en groupe ;<br>• pendant la journée, en semaine ;<br>• gratuite.</p><p>Vous comparez ces quatre annonces. Pour chaque annonce, cochez (☒) OUI si cela correspond au critère ou NON si cela ne correspond pas.</p>', reading_text = null where id = 'lo22mvemxfqi025';
update public.questions q set type = v.type, prompt = v.prompt, payload = v.payload, answer_key = v.answer_key, explanation = v.explanation
from (values
  (1, 'tableau', 'Pour chaque annonce, cochez OUI ou NON.', '{"colonnes":[{"id":"lo22mvemxfqi025c1","titre":"Stage de robotique","texte":"<p>Pendant les vacances de printemps, le club Les Bricodeurs propose un stage de cinq matinées, du lundi au vendredi, de 9 h à 12 h. Par équipes de trois, les jeunes de 12 à 16 ans construisent un petit robot qu''ils programment eux-mêmes. Le stage coûte 80 €, matériel compris ; une réduction est accordée aux familles nombreuses. Le vendredi, les familles sont invitées à venir voir les robots en action.</p>"},{"id":"lo22mvemxfqi025c2","titre":"Atelier photo au smartphone","texte":"<p>Deux samedis matin pour apprendre à faire de belles photos avec son téléphone : cadrage, lumière, retouche. L''atelier est gratuit grâce au soutien de la mairie, mais il est réservé aux jeunes de 15 à 18 ans. Chacun travaille sur son propre projet, avec les conseils individuels d''un photographe professionnel. Les plus belles images seront exposées dans le hall de la mairie.</p>"},{"id":"lo22mvemxfqi025c3","titre":"Sortie nature","texte":"<p>La maison de la nature organise chaque mercredi des vacances une sortie à la journée, de 9 h à 17 h, pour les 10-15 ans. Les jeunes partent à douze avec deux animateurs pour observer les oiseaux et apprendre à s''orienter avec une carte. La sortie est entièrement gratuite ; il suffit d''apporter un pique-nique et de bonnes chaussures.</p>"},{"id":"lo22mvemxfqi025c4","titre":"Tournois de jeux vidéo","texte":"<p>Le cybercafé Le Pixel organise des tournois en équipe le vendredi et le samedi soir, de 19 h à 23 h, sur grand écran. Ils sont ouverts aux joueurs à partir de 16 ans, sur présentation d''une pièce d''identité. Entrée : 5 € la soirée, boissons comprises. Les meilleures équipes gagnent des bons d''achat.</p>"}],"criteres":[{"id":"lo22mvemxfqi025t1","texte":"Âge"},{"id":"lo22mvemxfqi025t2","texte":"Groupe"},{"id":"lo22mvemxfqi025t3","texte":"Horaires"},{"id":"lo22mvemxfqi025t4","texte":"Prix"}]}'::jsonb, '{"answers":{"lo22mvemxfqi025t1_lo22mvemxfqi025c1":"OUI","lo22mvemxfqi025t2_lo22mvemxfqi025c1":"OUI","lo22mvemxfqi025t3_lo22mvemxfqi025c1":"OUI","lo22mvemxfqi025t4_lo22mvemxfqi025c1":"NON","lo22mvemxfqi025t1_lo22mvemxfqi025c2":"NON","lo22mvemxfqi025t2_lo22mvemxfqi025c2":"NON","lo22mvemxfqi025t3_lo22mvemxfqi025c2":"NON","lo22mvemxfqi025t4_lo22mvemxfqi025c2":"OUI","lo22mvemxfqi025t1_lo22mvemxfqi025c3":"OUI","lo22mvemxfqi025t2_lo22mvemxfqi025c3":"OUI","lo22mvemxfqi025t3_lo22mvemxfqi025c3":"OUI","lo22mvemxfqi025t4_lo22mvemxfqi025c3":"OUI","lo22mvemxfqi025t1_lo22mvemxfqi025c4":"NON","lo22mvemxfqi025t2_lo22mvemxfqi025c4":"OUI","lo22mvemxfqi025t3_lo22mvemxfqi025c4":"NON","lo22mvemxfqi025t4_lo22mvemxfqi025c4":"NON"}}'::jsonb, 'Robotique: « les jeunes de 12 à 16 ans » (OUI), « Par équipes de trois » (OUI), « du lundi au vendredi, de 9 h à 12 h » (OUI), « Le stage coûte 80 € » (NON). Photo: « réservé aux jeunes de 15 à 18 ans » (NON), « Chacun travaille sur son propre projet » (NON), « Deux samedis matin » (NON), « L''atelier est gratuit » (OUI). Sortie nature: « pour les 10-15 ans » (OUI), « Les jeunes partent à douze » (OUI), « chaque mercredi des vacances » (OUI), « entièrement gratuite » (OUI). Jeux vidéo: « à partir de 16 ans » (NON), « tournois en équipe » (OUI), « le vendredi et le samedi soir » (NON), « 5 € la soirée » (NON).')
) as v(ord, type, prompt, payload, answer_key, explanation)
