-- lo22mvemxfqj026
update public.exercises set consigne = '<p>Lisez l''article puis répondez aux questions.</p>', reading_text = '<p><strong>Réseaux sociaux avant 15 ans : une interdiction votée… puis bloquée</strong></p><p>Le 21 juillet 2026, au terme de plusieurs mois de débats souvent tendus, les députés et les sénateurs ont adopté une loi que de nombreux parents attendaient avec impatience. À partir du 1er septembre, les jeunes de moins de 15 ans ne pourraient plus créer de compte sur les réseaux sociaux, et les comptes déjà ouverts devaient être supprimés avant le 1er janvier 2027. La France devenait ainsi le premier pays de l''Union européenne à voter une telle interdiction générale, une décision présentée par ses défenseurs comme un signal fort envoyé aux plateformes.</p><p>Pourtant, la mesure n''est jamais entrée en vigueur. Saisi par des députés, le Conseil constitutionnel l''a censurée le 14 août. Contrairement à ce que certains ont cru comprendre, les juges n''ont pas contesté l''objectif de protéger les adolescents. Ce qu''ils ont reproché au texte, c''est d''aller trop loin. D''abord, il pouvait concerner des services sans danger prouvé pour les jeunes. Ensuite, il limitait la liberté d''expression. Enfin, il obligeait à vérifier l''âge de tous les utilisateurs, adultes compris, sans préciser comment leurs données personnelles seraient protégées.</p><p>Ce dernier point est loin d''être un détail. Pour prouver qu''il a plus de 15 ans, un utilisateur doit bien fournir une information sur son identité, et il faut donc qu''un organisme la conserve, au moins pour un temps. Autrement dit, pour protéger une partie de la population, on risquait de demander à tout le monde de se faire contrôler.</p><p>Une autre partie de la loi, en revanche, a survécu à la décision des juges. Depuis la rentrée 2026, l''interdiction du téléphone portable, qui existait déjà à l''école et au collège, s''applique aussi au lycée. Chaque établissement fixe les règles précises dans son règlement intérieur, ce qui peut expliquer des différences d''un lycée à l''autre.</p><p>Le débat est donc loin d''être clos. Le gouvernement doit présenter un nouveau projet avant le printemps 2027, en tenant compte cette fois des objections du Conseil constitutionnel. De son côté, la Commission européenne prépare un outil commun de vérification de l''âge, sur lequel travaillent sept pays, dont la France. Une solution européenne aurait au moins un avantage : les plateformes ne pourraient plus invoquer la diversité des règles nationales pour ne rien changer. Reste une question, qui est au cœur de toutes les discussions : comment protéger les plus jeunes sans surveiller tout le monde ?</p><p><p><small><em>Texte rédigé par FRACILE à partir de : Toute l''Europe, « Les députés et sénateurs français approuvent l''interdiction de l''accès aux réseaux sociaux pour les moins de 15 ans », 21 juillet 2026 (touteleurope.eu) ; Toute l''Europe, « Pourquoi l''interdiction des réseaux sociaux aux moins de 15 ans reste un casse-tête en France et en Europe », mis à jour le 17 septembre 2026 (touteleurope.eu).</em></small></p></p>' where id = 'lo22mvemxfqj026';
update public.questions q set type = v.type, prompt = v.prompt, payload = v.payload, answer_key = v.answer_key, explanation = v.explanation
from (values
  (1, 'qcm', 'Selon l''article, la loi adoptée en juillet 2026…', '{"options":["visait aussi les comptes déjà existants.","ne concernait que les nouveaux téléphones.","devait s''appliquer dès le 21 juillet."],"heSo":4}'::jsonb, '{"answer":0}'::jsonb, 'Luật không chỉ cấm tạo tài khoản mới: « les comptes déjà ouverts devaient être supprimés avant le 1er janvier 2027 ».'),
  (2, 'vf', 'Avec cette loi, la France était le premier pays de l''Union européenne à voter une interdiction générale de ce type.', '{"heSo":5}'::jsonb, '{"answer":0,"justification":"La France devenait ainsi le premier pays de l''Union européenne à voter une telle interdiction générale"}'::jsonb, null),
  (3, 'qcm', 'Pourquoi le Conseil constitutionnel a-t-il censuré la mesure ?', '{"options":["Il contestait l''idée même de protéger les adolescents.","Il voulait seulement en retarder l''application.","Il l''a jugée excessive."],"heSo":4}'::jsonb, '{"answer":2}'::jsonb, '« Ce qu''ils ont reproché au texte, c''est d''aller trop loin ». Bài nói rõ các thẩm phán « n''ont pas contesté l''objectif de protéger les adolescents ».'),
  (4, 'vf', 'Le texte prévoyait de vérifier l''âge des seuls utilisateurs mineurs.', '{"heSo":5}'::jsonb, '{"answer":1,"justification":"il obligeait à vérifier l''âge de tous les utilisateurs, adultes compris"}'::jsonb, null),
  (5, 'qcm', 'D''après le troisième paragraphe, vérifier l''âge pose problème parce que…', '{"options":["les adolescents mentent souvent sur leur âge.","les plateformes refusent de payer ce contrôle.","cela oblige à garder des données sur l''identité."],"heSo":4}'::jsonb, '{"answer":2}'::jsonb, '« un utilisateur doit bien fournir une information sur son identité, et il faut donc qu''un organisme la conserve ».'),
  (6, 'qcm', 'Que dit l''article de l''interdiction du portable au lycée ?', '{"options":["Ses règles varient selon l''établissement.","Elle a été annulée par les juges.","Elle remplace celle qui existait au collège."],"heSo":4}'::jsonb, '{"answer":0}'::jsonb, '« Chaque établissement fixe les règles précises dans son règlement intérieur ». Phần này « a survécu à la décision des juges », nên không bị huỷ.'),
  (7, 'qcm', 'Quel serait l''intérêt d''un outil européen de vérification de l''âge ?', '{"options":["Il coûterait moins cher que les outils de chaque pays.","Il permettrait d''interdire les réseaux sociaux dans toute l''Europe.","Les plateformes perdraient une excuse pour ne rien faire."],"heSo":4}'::jsonb, '{"answer":2}'::jsonb, '« les plateformes ne pourraient plus invoquer la diversité des règles nationales pour ne rien changer ».'),
  (8, 'qcm', 'Quelle difficulté l''article met-il en avant à la fin ?', '{"options":["trouver de l''argent pour financer la loi","concilier protection des mineurs et vie privée","convaincre les parents de l''utilité de la mesure"],"heSo":4}'::jsonb, '{"answer":1}'::jsonb, 'Câu kết: « comment protéger les plus jeunes sans surveiller tout le monde ? ».')
) as v(ord, type, prompt, payload, answer_key, explanation)
where q.exercise_id = 'lo22mvemxfqj026' and q.ord = v.ord;
delete from public.questions where exercise_id = 'lo22mvemxfqj026' and ord > 8;
